import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.C0KMm31j.js";const n="/Nav2ArticlesSite/article-assets/2026-08-13/nav2_regulated_local_costmap_cover.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/nav2_regulated_local_costmap_01_launch_config.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/nav2_regulated_local_costmap_02_lifecycle_subscription.png",p="/Nav2ArticlesSite/article-assets/2026-08-13/nav2_regulated_local_costmap_03_scan_tf_buffer.png",c="/Nav2ArticlesSite/article-assets/2026-08-13/nav2_regulated_local_costmap_04_voxel_fusion.png",r="/Nav2ArticlesSite/article-assets/2026-08-13/nav2_regulated_local_costmap_05_threads_control.png",d="/Nav2ArticlesSite/article-assets/2026-08-13/nav2_regulated_local_costmap_06_boundaries.png",b=JSON.parse('{"title":"一帧激光如何变成控制器手里的避障地图？拆解 Nav2 局部 Costmap 全数据流","description":"局部 Costmap 看起来像一张不断刷新的二维图片，但在当前 nav2regulatedmodules 中，它其实是一条横跨 Launch、ROS 参数、Lifecycle、TF、消息过滤、点云缓存、三维体素、二维代价融合和 RPP 控制器的进程内数据链。","frontmatter":{"title":"一帧激光如何变成控制器手里的避障地图？拆解 Nav2 局部 Costmap 全数据流","description":"局部 Costmap 看起来像一张不断刷新的二维图片，但在当前 nav2regulatedmodules 中，它其实是一条横跨 Launch、ROS 参数、Lifecycle、TF、消息过滤、点云缓存、三维体素、二维代价融合和 RPP 控制器的进程内数据链。","date":"2026-08-13","topic":"Nav2 工程实践","section":"四 · 代价地图与安全","readingTime":15,"source":"2026-08-13/nav2_regulated_modules_local_costmap_full_dataflow.md","status":"published","cover":"/article-assets/2026-08-13/nav2_regulated_local_costmap_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-regulated-modules-local-costmap-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一帧激光如何变成控制器手里的避障地图？拆解 Nav2 局部 Costmap 全数据流"}],["meta",{"property":"og:description","content":"局部 Costmap 看起来像一张不断刷新的二维图片，但在当前 nav2regulatedmodules 中，它其实是一条横跨 Launch、ROS 参数、Lifecycle、TF、消息过滤、点云缓存、三维体素、二维代价融合和 RPP 控制器的进程内数据链。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-regulated-modules-local-costmap-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/nav2_regulated_local_costmap_cover.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"一帧激光如何变成控制器手里的避障地图？拆解 Nav2 局部 Costmap 全数据流"}],["meta",{"name":"twitter:description","content":"局部 Costmap 看起来像一张不断刷新的二维图片，但在当前 nav2regulatedmodules 中，它其实是一条横跨 Launch、ROS 参数、Lifecycle、TF、消息过滤、点云缓存、三维体素、二维代价融合和 RPP 控制器的进程内数据链。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/nav2_regulated_local_costmap_cover.png"}]],"prev":{"text":"机器人明明没撞上，速度为什么先被“截胡”？一份可落地的 Nav2 Collision Monitor 配置指南","link":"/nav2/nav2-collision-monitor-configuration-guide"},"next":{"text":"规划、控制、恢复都在借谁的手？逐函数拆解 Nav2 公共底座 nav2_util","link":"/nav2/nav2-util-source-walkthrough"}},"headers":[],"relativePath":"nav2/nav2-regulated-modules-local-costmap-full-dataflow.md","filePath":"nav2/nav2-regulated-modules-local-costmap-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/nav2-regulated-modules-local-costmap-full-dataflow.md"};function k(g,a,u,m,_,E){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="一帧激光如何变成控制器手里的避障地图-拆解-nav2-局部-costmap-全数据流" tabindex="-1">一帧激光如何变成控制器手里的避障地图？拆解 Nav2 局部 Costmap 全数据流 <a class="header-anchor" href="#一帧激光如何变成控制器手里的避障地图-拆解-nav2-局部-costmap-全数据流" aria-label="Permalink to &quot;一帧激光如何变成控制器手里的避障地图？拆解 Nav2 局部 Costmap 全数据流&quot;">​</a></h1><p><img src="'+n+'" alt="封面：激光、体素地图与机器人控制闭环"></p><p>局部 Costmap 看起来像一张不断刷新的二维图片，但在当前 <code>nav2_regulated_modules</code> 中，它其实是一条横跨 Launch、ROS 参数、Lifecycle、TF、消息过滤、点云缓存、三维体素、二维代价融合和 RPP 控制器的进程内数据链。</p><p>这条链最容易被说错的地方有两个：系统订阅的不是点云 Topic，而是 <code>/c200_lidar_node/scan</code> 上的 <code>LaserScan</code>，点云只是在回调内部生成的中间数据；RPP 也不是订阅发布出来的 Costmap Topic，而是直接持有 Controller Server 内嵌 <code>Costmap2DROS</code> 的共享指针。</p><p>本文以当前 <code>learningnav2/nav2_regulated_modules/launch/regulated_modules.launch.py</code>、<code>regulated_modules.yaml</code>、<code>nav2_controller</code>、<code>nav2_costmap_2d</code> 和 RPP 源码为基线，把一帧激光怎样最终影响线速度、角速度和碰撞判定完整串起来。</p><p><img src="'+l+`" alt="图 1：从 Launch 到控制输出的完整装配链"></p><h2 id="一、先给结论-控制器使用的是共享内存地图" tabindex="-1">一、先给结论：控制器使用的是共享内存地图 <a class="header-anchor" href="#一、先给结论-控制器使用的是共享内存地图" aria-label="Permalink to &quot;一、先给结论：控制器使用的是共享内存地图&quot;">​</a></h2><p>当前链路可以压缩成下面这段：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>regulated_modules.launch.py</span></span>
<span class="line"><span>  → RewrittenYaml(configured_params)</span></span>
<span class="line"><span>  → ControllerServer</span></span>
<span class="line"><span>  → 内嵌 Costmap2DROS(&quot;local_costmap&quot;)</span></span>
<span class="line"><span>  → VoxelLayer 订阅 LaserScan</span></span>
<span class="line"><span>  → TF 门控后投影成 PointCloud2</span></span>
<span class="line"><span>  → ObservationBuffer 保存 map 坐标系观测</span></span>
<span class="line"><span>  → 5 Hz 更新 VoxelLayer 与 InflationLayer</span></span>
<span class="line"><span>  → combined_costmap_ 完成二维风险场</span></span>
<span class="line"><span>  → RPP 在 20 Hz 控制循环中锁图读取</span></span>
<span class="line"><span>  → 代价减速 + 运动弧 Footprint 碰撞预测</span></span>
<span class="line"><span>  → cmd_vel_nav</span></span>
<span class="line"><span>  → Velocity Smoother</span></span>
<span class="line"><span>  → /cmd_vel 或 fixed_path 的 Collision Monitor 安全链</span></span></code></pre></div><p>这里没有“Costmap 节点发布一张地图，RPP 再从 Topic 订阅回来”的过程。Controller Server 构造时创建局部 Costmap 对象，配置 RPP 插件时把同一个对象传进去。Costmap 对外发布主要服务 RViz 和调试工具，控制器读取的是进程内 Master Costmap。</p><h2 id="二、launch-怎样把参数送到内嵌局部地图" tabindex="-1">二、Launch 怎样把参数送到内嵌局部地图 <a class="header-anchor" href="#二、launch-怎样把参数送到内嵌局部地图" aria-label="Permalink to &quot;二、Launch 怎样把参数送到内嵌局部地图&quot;">​</a></h2><h3 id="_2-1-params-file-默认指向哪份配置" tabindex="-1">2.1 <code>params_file</code> 默认指向哪份配置 <a class="header-anchor" href="#_2-1-params-file-默认指向哪份配置" aria-label="Permalink to &quot;2.1 \`params_file\` 默认指向哪份配置&quot;">​</a></h3><p>Launch 参数 <code>params_file</code> 的默认值是包内 <code>params/regulated_modules.yaml</code>。源码随后用 <code>RewrittenYaml</code> 处理 <code>use_sim_time</code>、<code>autostart</code>、地图路径和 namespace，结果包装成 <code>configured_params</code>。</p><p><code>controller_server</code> 节点的 <code>parameters</code> 接收这份 <code>configured_params</code>。所以 YAML 中：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">local_costmap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  local_costmap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ros__parameters</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>并不是给一个 Launch 中显式声明的独立 <code>local_costmap</code> 进程使用，而是给 Controller Server 内部创建的同名 LifecycleNode 使用。</p><h3 id="_2-2-costmap-ros-configure-到底配置了什么" tabindex="-1">2.2 <code>costmap_ros_-&gt;configure()</code> 到底配置了什么 <a class="header-anchor" href="#_2-2-costmap-ros-configure-到底配置了什么" aria-label="Permalink to &quot;2.2 \`costmap_ros_-&gt;configure()\` 到底配置了什么&quot;">​</a></h3><p><code>ControllerServer</code> 构造函数执行：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">costmap_ros_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make_shared</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nav2_costmap_2d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Costmap2DROS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;local_costmap&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get_namespace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;local_costmap&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>进入 <code>ControllerServer::on_configure()</code> 后，<code>costmap_ros_-&gt;configure()</code> 触发内嵌 LifecycleNode 的 <code>Costmap2DROS::on_configure()</code>。它会读取的正是上述嵌套命名空间下的参数，而不是 Controller Server 顶层的控制器参数。</p><p>紧接着创建的 <code>nav2_util::NodeThread</code> 负责 spin 这个内嵌节点，使 TF、LaserScan、Footprint 和服务回调真正获得执行机会。</p><h3 id="_2-3-当前局部-costmap-的有效尺寸" tabindex="-1">2.3 当前局部 Costmap 的有效尺寸 <a class="header-anchor" href="#_2-3-当前局部-costmap-的有效尺寸" aria-label="Permalink to &quot;2.3 当前局部 Costmap 的有效尺寸&quot;">​</a></h3><p>当前参数是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global_frame       map</span></span>
<span class="line"><span>robot_base_frame   base_link</span></span>
<span class="line"><span>rolling_window     true</span></span>
<span class="line"><span>width              7 m</span></span>
<span class="line"><span>height             5 m</span></span>
<span class="line"><span>resolution         0.05 m/cell</span></span>
<span class="line"><span>plugins            voxel_layer → inflation_layer</span></span></code></pre></div><p>因此二维栅格尺寸为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>size_x = 7 / 0.05 = 140 cells</span></span>
<span class="line"><span>size_y = 5 / 0.05 = 100 cells</span></span></code></pre></div><p>机器人 Footprint 是前后半长 <code>0.6 m</code>、左右半宽 <code>0.4 m</code> 的矩形。这个几何既参与 Costmap 的车体内部清理，也参与 RPP 的完整足迹碰撞检查。</p><h2 id="三、原点不是从地图文件里读出来的" tabindex="-1">三、原点不是从地图文件里读出来的 <a class="header-anchor" href="#三、原点不是从地图文件里读出来的" aria-label="Permalink to &quot;三、原点不是从地图文件里读出来的&quot;">​</a></h2><h3 id="_3-1-get-parameter-origin-x-origin-x-的来源" tabindex="-1">3.1 <code>get_parameter(&quot;origin_x&quot;, origin_x_)</code> 的来源 <a class="header-anchor" href="#_3-1-get-parameter-origin-x-origin-x-的来源" aria-label="Permalink to &quot;3.1 \`get_parameter(&quot;origin_x&quot;, origin_x_)\` 的来源&quot;">​</a></h3><p><code>Costmap2DROS</code> 构造时声明 <code>origin_x</code> 和 <code>origin_y</code>，默认值都是 <code>0.0</code>。当前局部 Costmap YAML 没有覆写这两个参数，因此 <code>get_parameter()</code> 初次取得的是默认值。</p><p>这个初值只用于 configure 阶段首次分配 <code>140 × 100</code> 栅格。因为当前启用了 <code>rolling_window: true</code>，它不会长期作为局部地图固定原点。</p><h3 id="_3-2-滚动窗口每轮怎样重算原点" tabindex="-1">3.2 滚动窗口每轮怎样重算原点 <a class="header-anchor" href="#_3-2-滚动窗口每轮怎样重算原点" aria-label="Permalink to &quot;3.2 滚动窗口每轮怎样重算原点&quot;">​</a></h3><p><code>LayeredCostmap::updateMap(robot_x, robot_y, robot_yaw)</code> 每轮根据机器人在 <code>map</code> 中的位置计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>new_origin_x = robot_x - 7 / 2</span></span>
<span class="line"><span>new_origin_y = robot_y - 5 / 2</span></span></code></pre></div><p>也就是说，局部窗口始终以机器人为中心，X 方向覆盖机器人前后各约 <code>3.5 m</code>，Y 方向覆盖左右各约 <code>2.5 m</code>。窗口移动时，<code>updateOrigin()</code> 尽量保留重叠区域的旧栅格，再为新进入窗口的区域建立默认值。</p><p>所以当前局部地图原点的真实来源是“机器人实时 <code>map</code> 位姿减去半个窗口尺寸”，不是静态地图 YAML 的 <code>origin</code>，也不是雷达坐标原点。</p><h2 id="四、configure-为什么先创建订阅又立刻退订" tabindex="-1">四、Configure 为什么先创建订阅又立刻退订 <a class="header-anchor" href="#四、configure-为什么先创建订阅又立刻退订" aria-label="Permalink to &quot;四、Configure 为什么先创建订阅又立刻退订&quot;">​</a></h2><p><img src="`+o+`" alt="图 2：Lifecycle 与 LaserScan 订阅器状态转换"></p><h3 id="_4-1-while-ss-source-在遍历什么" tabindex="-1">4.1 <code>while (ss &gt;&gt; source)</code> 在遍历什么 <a class="header-anchor" href="#_4-1-while-ss-source-在遍历什么" aria-label="Permalink to &quot;4.1 \`while (ss &gt;&gt; source)\` 在遍历什么&quot;">​</a></h3><p>VoxelLayer 继承 ObstacleLayer，初始化时先执行 <code>ObstacleLayer::onInitialize()</code>。源码把 <code>observation_sources</code> 读成一个普通字符串：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringstream</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ss</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">topics_string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::string source;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (ss </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> source) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 为每个 source 读取私有参数并创建数据通道</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>operator&gt;&gt;</code> 会跳过空格、Tab 和换行，再读取一个由空白分隔的单词。当前参数是：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">observation_sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scan</span></span></code></pre></div><p>因此循环只执行一次，<code>source == &quot;scan&quot;</code>。如果配置成 <code>scan scan2</code>，循环会执行两次，依次读取：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>voxel_layer.scan.topic</span></span>
<span class="line"><span>voxel_layer.scan.data_type</span></span>
<span class="line"><span>voxel_layer.scan.marking</span></span>
<span class="line"><span>voxel_layer.scan.clearing</span></span>
<span class="line"><span></span></span>
<span class="line"><span>voxel_layer.scan2.topic</span></span>
<span class="line"><span>voxel_layer.scan2.data_type</span></span>
<span class="line"><span>voxel_layer.scan2.marking</span></span>
<span class="line"><span>voxel_layer.scan2.clearing</span></span></code></pre></div><p>这段循环的作用不是读取激光消息，而是根据源名批量搭建每个传感器的 ObservationBuffer、Subscriber 和 MessageFilter。</p><h3 id="_4-2-带参构造函数已经订阅了-topic" tabindex="-1">4.2 带参构造函数已经订阅了 Topic <a class="header-anchor" href="#_4-2-带参构造函数已经订阅了-topic" aria-label="Permalink to &quot;4.2 带参构造函数已经订阅了 Topic&quot;">​</a></h3><p>LaserScan 分支创建：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sub </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::make_shared</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">message_filters</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::Subscriber</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  sensor_msgs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::LaserScan,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  rclcpp_lifecycle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::LifecycleNode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    node, topic, custom_qos_profile, sub_opt);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sub-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unsubscribe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p><code>message_filters::Subscriber</code> 的带参构造函数内部立即调用 <code>subscribe(node, topic, qos, options)</code>，最终执行 <code>node-&gt;create_subscription()</code>。所以构造完成时，底层 ROS 订阅确实已经存在。</p><p>紧随其后的 <code>unsubscribe()</code> 只执行：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sub_.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>它释放底层 <code>rclcpp::Subscription</code>，停止接收数据，但不会清空先前保存的 <code>topic_</code>、<code>qos_</code>、<code>options_</code> 和节点指针。</p><h3 id="_4-3-这是一种-lifecycle-资源管理方式" tabindex="-1">4.3 这是一种 Lifecycle 资源管理方式 <a class="header-anchor" href="#_4-3-这是一种-lifecycle-资源管理方式" aria-label="Permalink to &quot;4.3 这是一种 Lifecycle 资源管理方式&quot;">​</a></h3><p>Configure 的职责是准备对象和连接关系，但节点还处于 inactive，不应该持续接收传感器数据。于是代码先利用构造函数保存完整订阅配置，再主动退订。</p><p>Costmap 激活时，<code>ObstacleLayer::activate()</code> 先清理 MessageFilter 队列，再调用无参 <code>subscribe()</code>。该函数使用保存的节点、Topic、QoS 和 options 重建底层订阅。停用时再次调用 <code>unsubscribe()</code>，下一次激活仍可恢复。</p><p>这段代码的状态语义是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>configure   对象存在，订阅配置存在，底层 ROS subscription 不存在</span></span>
<span class="line"><span>activate    底层 ROS subscription 被重建，开始收 LaserScan</span></span>
<span class="line"><span>deactivate  底层 ROS subscription 被释放，配置继续保留</span></span>
<span class="line"><span>cleanup     插件和缓存对象整体销毁</span></span></code></pre></div><h2 id="五、收到的明明是-laserscan-点云从哪里来" tabindex="-1">五、收到的明明是 LaserScan，点云从哪里来 <a class="header-anchor" href="#五、收到的明明是-laserscan-点云从哪里来" aria-label="Permalink to &quot;五、收到的明明是 LaserScan，点云从哪里来&quot;">​</a></h2><p><img src="`+p+`" alt="图 3：LaserScan 到 ObservationBuffer 的数据形态变化"></p><h3 id="_5-1-当前订阅端的真实类型" tabindex="-1">5.1 当前订阅端的真实类型 <a class="header-anchor" href="#_5-1-当前订阅端的真实类型" aria-label="Permalink to &quot;5.1 当前订阅端的真实类型&quot;">​</a></h3><p>当前参数明确写着：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">topic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/c200_lidar_node/scan</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">data_type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LaserScan&quot;</span></span></code></pre></div><p>因此 ROS 通信层接收的是 <code>sensor_msgs/msg/LaserScan</code>。把这条链称为“订阅激光点云”并不精确，更准确的说法是“订阅二维激光扫描，并在 Costmap 内部投影成点云”。</p><h3 id="_5-2-messagefilter-是-tf-门卫" tabindex="-1">5.2 MessageFilter 是 TF 门卫 <a class="header-anchor" href="#_5-2-messagefilter-是-tf-门卫" aria-label="Permalink to &quot;5.2 MessageFilter 是 TF 门卫&quot;">​</a></h3><p>Subscriber 并没有直接绑定 <code>laserScanCallback()</code>，它先连接 <code>tf2_ros::MessageFilter</code>。过滤器的目标坐标系是局部 Costmap 的 <code>global_frame</code>，当前为 <code>map</code>，队列长度是 <code>50</code>。</p><p>当一帧扫描到达时，过滤器检查扫描时间戳对应的传感器坐标系能否转换到 <code>map</code>。只有 TF 可用，回调才会继续；TF 长时间缺失、时间戳落在 Buffer 范围外或队列溢出时，这帧数据不会进入 ObservationBuffer。</p><p>这里用到的 <code>tf2_ros::Buffer</code> 在 <code>Costmap2DROS::on_configure()</code> 中由：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tf_buffer_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make_shared</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tf2_ros</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Buffer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get_clock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tf_listener_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make_shared</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tf2_ros</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TransformListener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tf_buffer_);</span></span></code></pre></div><p>创建。Buffer 使用 Costmap 节点时钟管理带时间戳的变换缓存，Listener 将 <code>/tf</code> 和 <code>/tf_static</code> 数据写入 Buffer。MessageFilter、ObservationBuffer、机器人位姿查询和 RPP 路径变换共享这套 TF 数据。</p><h3 id="_5-3-laserscan-在回调里投影成-pointcloud2" tabindex="-1">5.3 LaserScan 在回调里投影成 PointCloud2 <a class="header-anchor" href="#_5-3-laserscan-在回调里投影成-pointcloud2" aria-label="Permalink to &quot;5.3 LaserScan 在回调里投影成 PointCloud2&quot;">​</a></h3><p>TF 门控通过后，<code>ObstacleLayer::laserScanCallback()</code> 使用 <code>laser_geometry::LaserProjection::transformLaserScanToPointCloud()</code> 生成 <code>PointCloud2</code>。随后回调锁住对应 ObservationBuffer，调用 <code>bufferCloud(cloud)</code>。</p><p><code>ObservationBuffer::bufferCloud()</code> 继续完成：</p><ul><li>选择显式 <code>sensor_frame</code>，或使用点云消息自身的 <code>frame_id</code>。</li><li>把传感器原点 <code>(0, 0, 0)</code> 变换到 <code>map</code>。</li><li>把整个 <code>PointCloud2</code> 变换到 <code>map</code>。</li><li>按最小和最大障碍高度过滤点。</li><li>为观测保存标障和清障距离。</li><li>更新 <code>last_updated_</code> 并清理超出保留时间的旧观测。</li></ul><p>此后 VoxelLayer 不再关心原始数据来自 LaserScan 还是原生 PointCloud2，它消费的是统一的 <code>Observation</code>：传感器原点、<code>map</code> 坐标点云和量程约束。</p><h2 id="六、同一帧观测为什么既能清障又能标障" tabindex="-1">六、同一帧观测为什么既能清障又能标障 <a class="header-anchor" href="#六、同一帧观测为什么既能清障又能标障" aria-label="Permalink to &quot;六、同一帧观测为什么既能清障又能标障&quot;">​</a></h2><p>当前 <code>scan</code> 同时配置：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">clearing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">marking</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">raytrace_max_range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">obstacle_max_range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.5</span></span></code></pre></div><p>初始化时，同一个 ObservationBuffer 会同时进入 <code>clearing_buffers_</code> 和 <code>marking_buffers_</code>。Costmap 更新线程读取的是同一帧观测，但用两套算法解释它。</p><p><img src="`+c+`" alt="图 4：VoxelLayer 标记、清除与 Inflation 融合"></p><h3 id="_6-1-clearing-表达-射线经过处是空的" tabindex="-1">6.1 Clearing 表达“射线经过处是空的” <a class="header-anchor" href="#_6-1-clearing-表达-射线经过处是空的" aria-label="Permalink to &quot;6.1 Clearing 表达“射线经过处是空的”&quot;">​</a></h3><p>VoxelLayer 从传感器原点向每个扫描端点做三维射线追踪，把沿途体素和二维投影清为自由空间。清障最大距离为 <code>3.0 m</code>。</p><p>动态障碍消失后，旧栅格不是因为“没有新点”自动清除，而是后续扫描射线明确穿过这片区域，证明它现在可见且为空。</p><h3 id="_6-2-marking-表达-射线终点有实体" tabindex="-1">6.2 Marking 表达“射线终点有实体” <a class="header-anchor" href="#_6-2-marking-表达-射线终点有实体" aria-label="Permalink to &quot;6.2 Marking 表达“射线终点有实体”&quot;">​</a></h3><p>标障分支计算命中点到传感器原点的三维距离。当前只有距离小于 <code>2.5 m</code>、高度不超过 <code>2.0 m</code>、并且能映射到体素网格的点才继续处理。</p><p>命中点先写入三维 VoxelGrid。当某个 XY 列达到 <code>mark_threshold</code>，对应二维栅格被写成 <code>LETHAL_OBSTACLE</code>。当前 <code>mark_threshold: 0</code>，意味着有效占用能非常直接地投影成二维致命障碍。</p><h3 id="_6-3-footprint-clearing-避免机器人标记自己" tabindex="-1">6.3 Footprint Clearing 避免机器人标记自己 <a class="header-anchor" href="#_6-3-footprint-clearing-避免机器人标记自己" aria-label="Permalink to &quot;6.3 Footprint Clearing 避免机器人标记自己&quot;">​</a></h3><p>VoxelLayer 更新完传感器障碍后，还会根据机器人当前 <code>x、y、yaw</code> 变换矩形 Footprint，并清理轮廓内部的障碍栅格。它的作用是减少车体反射、安装误差或近场噪声导致“机器人被自己的 Costmap 困住”。</p><h3 id="_6-4-inflationlayer-把一个点变成安全梯度" tabindex="-1">6.4 InflationLayer 把一个点变成安全梯度 <a class="header-anchor" href="#_6-4-inflationlayer-把一个点变成安全梯度" aria-label="Permalink to &quot;6.4 InflationLayer 把一个点变成安全梯度&quot;">​</a></h3><p>LayeredCostmap 按配置顺序执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>voxel_layer</span></span>
<span class="line"><span>inflation_layer</span></span></code></pre></div><p>VoxelLayer 先提供自由空间和致命障碍，InflationLayer 再以 <code>0.45 m</code> 为膨胀半径、<code>5.0</code> 为代价衰减系数，在致命障碍周围生成连续梯度。</p><p>RPP 的代价减速不是只看 <code>254</code> 这个致命值。它读取机器人所在栅格的膨胀代价，并用同样的 <code>inflation_cost_scaling_factor=5.0</code> 反推出距障碍的大致距离。因此 RPP 参数中的衰减系数必须与 InflationLayer 一致，否则控制器会用错误模型解释 Costmap 代价。</p><h2 id="七、5-hz-更新和-2-hz-发布不是一回事" tabindex="-1">七、5 Hz 更新和 2 Hz 发布不是一回事 <a class="header-anchor" href="#七、5-hz-更新和-2-hz-发布不是一回事" aria-label="Permalink to &quot;七、5 Hz 更新和 2 Hz 发布不是一回事&quot;">​</a></h2><h3 id="_7-1-地图更新线程以-5-hz-融合" tabindex="-1">7.1 地图更新线程以 5 Hz 融合 <a class="header-anchor" href="#_7-1-地图更新线程以-5-hz-融合" aria-label="Permalink to &quot;7.1 地图更新线程以 5 Hz 融合&quot;">​</a></h3><p>激活 Costmap 时，<code>Costmap2DROS</code> 创建 <code>map_update_thread</code>，以 <code>update_frequency=5.0</code> 调用 <code>updateMap()</code>。每轮先通过 TF 查询 <code>map → base_link</code> 得到机器人位姿，再进入 <code>LayeredCostmap::updateMap()</code>。</p><p>LayeredCostmap 持有 Master Costmap 互斥锁，完成下面这组原子流程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据机器人位姿移动滚动窗口</span></span>
<span class="line"><span>调用所有插件的 updateBounds()</span></span>
<span class="line"><span>把世界坐标更新范围换算成栅格窗口</span></span>
<span class="line"><span>重置需要重算的窗口</span></span>
<span class="line"><span>按顺序调用插件 updateCosts()</span></span>
<span class="line"><span>记录本轮有效边界</span></span></code></pre></div><p>当前没有 Costmap Filter，因此 VoxelLayer 和 InflationLayer 直接顺序写 <code>combined_costmap_</code>，它就是控制器最终读取的 Master Costmap。</p><h3 id="_7-2-对外发布只有-2-hz" tabindex="-1">7.2 对外发布只有 2 Hz <a class="header-anchor" href="#_7-2-对外发布只有-2-hz" aria-label="Permalink to &quot;7.2 对外发布只有 2 Hz&quot;">​</a></h3><p><code>publish_frequency=2.0</code> 控制 <code>Costmap2DPublisher</code> 多久发送一次 <code>costmap</code>、<code>costmap_raw</code> 或更新消息。它主要影响 RViz 和外部工具看到地图的刷新速度。</p><p>RPP 不走这个 Topic，因此不能根据 RViz 的 <code>2 Hz</code> 刷新速度推断控制器只拿到 <code>2 Hz</code> 地图。只要 5 Hz 更新线程完成一次融合，下一次 RPP 锁图时就能直接看到新结果。</p><h2 id="八、rpp-怎样把地图变成速度约束" tabindex="-1">八、RPP 怎样把地图变成速度约束 <a class="header-anchor" href="#八、rpp-怎样把地图变成速度约束" aria-label="Permalink to &quot;八、RPP 怎样把地图变成速度约束&quot;">​</a></h2><h3 id="_8-1-配置阶段保存的是同一个-costmap-对象" tabindex="-1">8.1 配置阶段保存的是同一个 Costmap 对象 <a class="header-anchor" href="#_8-1-配置阶段保存的是同一个-costmap-对象" aria-label="Permalink to &quot;8.1 配置阶段保存的是同一个 Costmap 对象&quot;">​</a></h3><p>Controller Server 加载控制器插件时调用：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">controller-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  node,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  controller_id,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  costmap_ros_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getTfBuffer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  costmap_ros_);</span></span></code></pre></div><p>RPP 在 <code>configure()</code> 中保存 <code>costmap_ros_</code>，并通过 <code>getCostmap()</code> 得到 Master Costmap 指针。这里没有序列化，没有 DDS，也没有中间消息副本。</p><h3 id="_8-2-每个控制周期都先锁住地图" tabindex="-1">8.2 每个控制周期都先锁住地图 <a class="header-anchor" href="#_8-2-每个控制周期都先锁住地图" aria-label="Permalink to &quot;8.2 每个控制周期都先锁住地图&quot;">​</a></h3><p><code>ControllerServer</code> 以 <code>20 Hz</code> 调用 RPP 的 <code>computeVelocityCommands()</code>。RPP 进入函数后同时保护动态重配置状态和 Costmap：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lock_guard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mutex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lock_reinit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mutex_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unique_lock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Costmap2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mutex_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">costmap</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getMutex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><p>因此它看到的是一张已经完成本轮融合的完整地图，不会读到 VoxelLayer 写了一半、InflationLayer 还没处理的中间状态。代价是 RPP 计算期间，地图更新线程需要等待同一把 Costmap 锁。</p><h3 id="_8-3-机器人当前位置的代价用于主动减速" tabindex="-1">8.3 机器人当前位置的代价用于主动减速 <a class="header-anchor" href="#_8-3-机器人当前位置的代价用于主动减速" aria-label="Permalink to &quot;8.3 机器人当前位置的代价用于主动减速&quot;">​</a></h3><p>RPP 的 <code>costAtPose(x, y)</code> 先把世界坐标转换成栅格索引，再读取一个 <code>unsigned char</code> 代价值。<code>applyConstraints()</code> 同时计算曲率限速和障碍代价限速，取两者中更低者，再叠加接近终点减速。</p><p>当前相关开关均已启用：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">use_regulated_linear_velocity_scaling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">use_cost_regulated_linear_velocity_scaling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">use_collision_detection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>所以局部 Costmap 会以两种方式影响速度：膨胀代价让机器人在靠近障碍时提前降速；致命障碍和 Footprint 检查则可能直接拒绝当前候选速度。</p><h3 id="_8-4-运动弧碰撞预测决定-能不能发这条速度" tabindex="-1">8.4 运动弧碰撞预测决定“能不能发这条速度” <a class="header-anchor" href="#_8-4-运动弧碰撞预测决定-能不能发这条速度" aria-label="Permalink to &quot;8.4 运动弧碰撞预测决定“能不能发这条速度”&quot;">​</a></h3><p>RPP 根据算出的线速度和角速度向前离散积分，预测范围不超过前视点，也不超过 <code>max_allowed_time_to_collision_up_to_carrot=1.0 s</code>。</p><p>每个预测位姿都调用 <code>footprintCostAtPose()</code>，用完整矩形 Footprint 检查局部 Costmap。发现致命碰撞后，<code>isCollisionImminent()</code> 返回 <code>true</code>，控制器抛出：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RegulatedPurePursuitController detected collision ahead!</span></span></code></pre></div><p>Controller Server 会按 <code>failure_tolerance</code> 决定短暂输出零速还是终止 FollowPath。这个错误并不只说明激光正前方有一个点，它还可能来自 Footprint 尺寸、膨胀参数、TF、残留障碍、窗口范围或预测运动弧。</p><h2 id="九、三类执行流怎样避免互相踩数据" tabindex="-1">九、三类执行流怎样避免互相踩数据 <a class="header-anchor" href="#九、三类执行流怎样避免互相踩数据" aria-label="Permalink to &quot;九、三类执行流怎样避免互相踩数据&quot;">​</a></h2><p><img src="`+r+`" alt="图 5：三类执行流、两组锁与四种频率"></p><p>当前系统至少有三类重要执行上下文：</p><ul><li>Costmap 回调执行器处理 LaserScan、TF 和其他 ROS 回调，将新点云写入 ObservationBuffer。</li><li><code>map_update_thread</code> 以 <code>5 Hz</code> 读取 ObservationBuffer，融合 VoxelLayer 和 InflationLayer。</li><li>Controller Server 的 FollowPath 执行流以 <code>20 Hz</code> 调用 RPP，读取 Master Costmap 并计算速度。</li></ul><p>ObservationBuffer 自己有锁，保护传感器回调写入与地图线程读取。Master Costmap 也有锁，保护插件融合与控制器读取。</p><p>频率关系为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LaserScan 输入频率    由雷达驱动决定</span></span>
<span class="line"><span>Costmap 内部更新      5 Hz</span></span>
<span class="line"><span>RPP 控制计算          20 Hz</span></span>
<span class="line"><span>Costmap 对外发布      2 Hz</span></span></code></pre></div><p>因此一份完整地图通常会被连续约四个控制周期读取。这里是“同一张内存地图被多次查询”，不是每次控制都复制一张地图，也不是控制循环会强制等待下一帧激光。</p><h2 id="十、观测缓存的默认值藏着什么风险" tabindex="-1">十、观测缓存的默认值藏着什么风险 <a class="header-anchor" href="#十、观测缓存的默认值藏着什么风险" aria-label="Permalink to &quot;十、观测缓存的默认值藏着什么风险&quot;">​</a></h2><h3 id="_10-1-observation-persistence-0-不是不保存" tabindex="-1">10.1 <code>observation_persistence=0</code> 不是不保存 <a class="header-anchor" href="#_10-1-observation-persistence-0-不是不保存" aria-label="Permalink to &quot;10.1 \`observation_persistence=0\` 不是不保存&quot;">​</a></h3><p>当前 YAML 没有显式设置 <code>observation_persistence</code>，所以使用默认 <code>0.0 s</code>。ObservationBuffer 每次把新观测放到链表头部，清理逻辑在保留时间为零时只留下最新观测。</p><p>它表达的是“不做多帧时间积累”，不是“回调结束后立刻没有数据”。Costmap 更新线程仍能读取最新一帧。</p><h3 id="_10-2-expected-update-rate-0-会关闭过期检查" tabindex="-1">10.2 <code>expected_update_rate=0</code> 会关闭过期检查 <a class="header-anchor" href="#_10-2-expected-update-rate-0-会关闭过期检查" aria-label="Permalink to &quot;10.2 \`expected_update_rate=0\` 会关闭过期检查&quot;">​</a></h3><p>当前也没有设置 <code>expected_update_rate</code>，默认值为 <code>0.0 s</code>。<code>ObservationBuffer::isCurrent()</code> 对零值直接返回 <code>true</code>。</p><p>这意味着雷达停止更新后，VoxelLayer 不会仅凭这个参数把自己标为 stale，Controller Server 的：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">costmap_ros_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isCurrent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // wait</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>也不会因为该扫描源超时而阻断控制。</p><p>如果工程目标是“雷达超过某个周期没数据就不允许继续控制”，应为该源配置合理的非零 <code>expected_update_rate</code>，并结合实际雷达频率、DDS 抖动和 TF 延迟验证，不能只依赖 Topic 名字存在。</p><h3 id="_10-3-0-8-m-体素高度与-2-0-m-障碍上限不一致" tabindex="-1">10.3 0.8 m 体素高度与 2.0 m 障碍上限不一致 <a class="header-anchor" href="#_10-3-0-8-m-体素高度与-2-0-m-障碍上限不一致" aria-label="Permalink to &quot;10.3 0.8 m 体素高度与 2.0 m 障碍上限不一致&quot;">​</a></h3><p>当前体素垂向范围为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>origin_z + z_voxels × z_resolution</span></span>
<span class="line"><span>= 0.0 + 16 × 0.05</span></span>
<span class="line"><span>= 0.8 m</span></span></code></pre></div><p>但 <code>max_obstacle_height</code> 是 <code>2.0 m</code>。高度过滤允许 <code>0～2.0 m</code> 的点进入 Observation，而 VoxelGrid 只能表示到约 <code>0.8 m</code>。变换后 Z 值超出体素范围的点会在 <code>worldToMap3D()</code> 失败后跳过。</p><p>对水平安装的二维雷达，这不一定造成实际问题，因为有效点的 Z 往往接近雷达安装高度；但如果传感器 TF 让点落在 <code>0.8 m</code> 以上，配置就会出现“消息收到了、点云也生成了、二维地图却没有障碍”的现象。最终判断必须核对真实 <code>sensor_frame → map</code> 变换和点云 Z 分布。</p><h2 id="十一、tf-故障会在哪些位置截断数据" tabindex="-1">十一、TF 故障会在哪些位置截断数据 <a class="header-anchor" href="#十一、tf-故障会在哪些位置截断数据" aria-label="Permalink to &quot;十一、TF 故障会在哪些位置截断数据&quot;">​</a></h2><p>TF 在这条链里不是一次查询，而是多处共同依赖：</p><ul><li>Costmap 激活时等待 <code>map ← base_link</code> 可用。</li><li>MessageFilter 等待每帧扫描时间戳对应的传感器坐标系到 <code>map</code> 变换。</li><li>LaserProjection 在扫描束时间模型下投影 LaserScan。</li><li>ObservationBuffer 变换传感器原点和完整 PointCloud2 到 <code>map</code>。</li><li>Costmap 更新线程查询机器人当前 <code>map</code> 位姿。</li><li>RPP 使用同一 TF Buffer 变换全局路径和机器人位姿。</li></ul><p>如果扫描 Topic 有频率但 Costmap 没障碍，排查重点不是“订阅是否创建”这一项，而要同时检查消息时间戳、<code>frame_id</code>、静态 TF、动态 TF 缓存范围和目标 <code>map</code> 坐标系。</p><p>如果 <code>Costmap2DROS::updateMap()</code> 取不到机器人位姿，它会跳过整轮地图融合。即使 ObservationBuffer 中有新点云，滚动窗口也无法根据机器人位置移动，插件不会进入正常更新链。</p><h2 id="十二、collision-monitor-为什么不能算作局部-costmap-的下一层" tabindex="-1">十二、Collision Monitor 为什么不能算作局部 Costmap 的下一层 <a class="header-anchor" href="#十二、collision-monitor-为什么不能算作局部-costmap-的下一层" aria-label="Permalink to &quot;十二、Collision Monitor 为什么不能算作局部 Costmap 的下一层&quot;">​</a></h2><p><img src="`+d+`" alt="图 6：局部 Costmap 与 Collision Monitor 的职责边界"></p><p>当前 Launch 还创建 Collision Monitor，并在 <code>fixed_path</code> 模式把 Velocity Smoother 输出送入其安全链。它可能订阅同一个 <code>/c200_lidar_node/scan</code>，但这不代表它消费局部 Costmap。</p><p>两条链的职责不同：</p><ul><li>局部 Costmap 把传感器历史、清障、体素占用和膨胀梯度融合成二维风险场，供 RPP 代价调速和运动弧碰撞检查。</li><li>Collision Monitor 自己创建 Source，直接把传感器点与 Polygon 或 Circle 区域比较，执行 STOP、SLOWDOWN 或 APPROACH 动作。</li></ul><p>它们没有共享 ObservationBuffer，也没有“RPP 发布 Costmap 给 Collision Monitor”的连接。即使使用同一束激光，两条链也会分别做订阅、TF 和数据处理。</p><p>这也是定位问题时必须分开的边界：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RPP 报 detected collision ahead</span></span>
<span class="line"><span>  → 优先检查局部 Costmap、Footprint、膨胀、预测弧和 TF</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终 /cmd_vel 被压低或归零，但 RPP 输出正常</span></span>
<span class="line"><span>  → 检查 Velocity Smoother 和 fixed_path Collision Monitor</span></span></code></pre></div><h2 id="十三、按数据流排查-比盯着-rviz-更可靠" tabindex="-1">十三、按数据流排查，比盯着 RViz 更可靠 <a class="header-anchor" href="#十三、按数据流排查-比盯着-rviz-更可靠" aria-label="Permalink to &quot;十三、按数据流排查，比盯着 RViz 更可靠&quot;">​</a></h2><h3 id="_13-1-先确认运行参数-而不是只看-yaml" tabindex="-1">13.1 先确认运行参数，而不是只看 YAML <a class="header-anchor" href="#_13-1-先确认运行参数-而不是只看-yaml" aria-label="Permalink to &quot;13.1 先确认运行参数，而不是只看 YAML&quot;">​</a></h3><p>Launch 支持自定义 <code>params_file</code>、namespace 和运行时重写。排查时应确认 <code>local_costmap.local_costmap</code> 的实际参数，尤其是 <code>global_frame</code>、尺寸、分辨率、插件顺序、<code>observation_sources</code> 和传感器 Topic。</p><h3 id="_13-2-再确认消息与-tf-是否在同一时间线上" tabindex="-1">13.2 再确认消息与 TF 是否在同一时间线上 <a class="header-anchor" href="#_13-2-再确认消息与-tf-是否在同一时间线上" aria-label="Permalink to &quot;13.2 再确认消息与 TF 是否在同一时间线上&quot;">​</a></h3><p>检查 LaserScan 的 <code>header.frame_id</code> 和时间戳，确认该时间点存在传感器到 <code>map</code> 的变换。Topic 有数据只能证明 Publisher 正常，不能证明 MessageFilter 已经放行。</p><h3 id="_13-3-再看-observation-与图层结果" tabindex="-1">13.3 再看 Observation 与图层结果 <a class="header-anchor" href="#_13-3-再看-observation-与图层结果" aria-label="Permalink to &quot;13.3 再看 Observation 与图层结果&quot;">​</a></h3><p>确认清障距离、标障距离、高度过滤、体素 Z 范围和 Footprint 是否符合真实安装。<code>publish_voxel_map: true</code> 可以辅助判断点有没有进入三维体素，而局部 Costmap 则显示二维投影与膨胀结果。</p><h3 id="_13-4-最后区分地图更新、地图发布和控制读取" tabindex="-1">13.4 最后区分地图更新、地图发布和控制读取 <a class="header-anchor" href="#_13-4-最后区分地图更新、地图发布和控制读取" aria-label="Permalink to &quot;13.4 最后区分地图更新、地图发布和控制读取&quot;">​</a></h3><p>内部更新是 <code>5 Hz</code>，外部发布是 <code>2 Hz</code>，控制读取是 <code>20 Hz</code> 的进程内共享访问。RViz 看起来慢半拍，不等于 RPP 同样慢；RPP 报碰撞，也不等于 Collision Monitor 做了停车裁决。</p><h2 id="十四、总结" tabindex="-1">十四、总结 <a class="header-anchor" href="#十四、总结" aria-label="Permalink to &quot;十四、总结&quot;">​</a></h2><p>当前 <code>nav2_regulated_modules</code> 的局部 Costmap 数据流，本质上是一套有生命周期、有 TF 时间门控、有缓存、有三维到二维投影、有插件顺序、有互斥锁保护的实时共享状态。</p><p>它从 <code>LaserScan</code> 开始，却不会以 LaserScan 结束。扫描经 MessageFilter 验证 TF 后被投影成 PointCloud2，ObservationBuffer 将它统一到 <code>map</code>，VoxelLayer 用同一帧数据清除自由空间并标记三维体素，InflationLayer 把致命障碍扩展为连续风险梯度，最终由 RPP 在同一进程内锁图读取。</p><p>理解这条链后，几个常见疑问就有了明确答案：<code>while (ss &gt;&gt; source)</code> 是在遍历传感器配置名；构造后 <code>unsubscribe()</code> 是为了遵守 Lifecycle；<code>origin_x</code> 在滚动窗口中会被机器人位姿持续替代；<code>publish_frequency</code> 不等于控制器读图频率；Collision Monitor 也不是 Costmap 的下游插件。</p><p>真正驱动控制的，不是 RViz 上那张图，而是刚刚完成插件融合、仍在进程内存中的 <code>combined_costmap_</code>。</p>`,171)])])}const v=s(h,[["render",k]]);export{b as __pageData,v as default};
